    func testSchemaIntegerDecimalsAndUnboundedAuditSequenceArePreserved() throws {
        let coordinates = try ContractCoding.canonicalDecode(AeostaraContract.AshState.self,from:Data(#"{"stateID":"decimal-bits","coordinates":[0.0,1e0,0,1.0,0,1,0,1,0],"sourceReference":"explicit-test","canonicalHash":"shape-only"}"#.utf8))
        XCTAssertEqual(coordinates.coordinates,[0,1,0,1,0,1,0,1,0])
        let source = #"{"auditEventID":"unbounded","eventSequence":1234567890123456789012345678901234567890,"eventType":"OBSERVE","diagnosticReference":{"diagnosticID":"root","chainRootReference":"root","diagnosticKind":"STATE_VALIDITY","ruleReferences":[{"ruleID":"ASH-STATE-STRUCTURE-001","sourceReference":"explicit-test","ruleFamily":"STATE"}]},"occurredAt":"test","details":{}}"#
        let event = try ContractCoding.canonicalDecode(AeostaraContract.AuditEvent.self,from:Data(source.utf8))
        XCTAssertEqual(event.eventSequence.decimalText,"1234567890123456789012345678901234567890");XCTAssertNil(event.eventSequence.intValue)
        XCTAssertEqual(try ContractCoding.canonicalDecode(AeostaraContract.AuditEvent.self,from:ContractCoding.canonicalEncode(event)),event)
        XCTAssertEqual(try JSONInteger(jsonValue:CanonicalJSON.parse("1.0")),JSONInteger(1))
        XCTAssertEqual(try JSONInteger(jsonValue:CanonicalJSON.parse("1e100")).decimalText,"1"+String(repeating:"0",count:100))
        XCTAssertEqual(try JSONInteger(jsonValue:CanonicalJSON.parse("-0.0")),JSONInteger(0))
        XCTAssertThrowsError(try JSONInteger(jsonValue:CanonicalJSON.parse("1.5")))
        XCTAssertThrowsError(try JSONInteger(jsonValue:.bool(true)))
        XCTAssertTrue(try JSONInteger(decimalText:"-9999999999999999999999999999") < JSONInteger(-1))
    }
    func testLexicalIntegerAdmissionNeverRoundsDecimalOrExponentTokens() throws {
        let root = try NativeSliceContext.make().inputDiagnosticChains[0].diagnostics[0]
        let reference = try AeostaraContract.DiagnosticReference(diagnosticID:root.diagnosticID,chainRootReference:root.chainRootReference,diagnosticKind:.MAPPING,ruleReferences:root.ruleReferences)
        let event = try AeostaraContract.AuditEvent(auditEventID:"exact-lexical-integer",eventSequence:1,eventType:.OBSERVE,diagnosticReference:reference,occurredAt:"explicit-test",details:.object([]))
        let template = String(decoding:try ContractCoding.canonicalEncode(event),as:UTF8.self)
        let tokens: [(String,String)] = [
            ("9007199254740993.0","9007199254740993"),
            ("9.007199254740993e15","9007199254740993"),
            ("9223372036854775808.0","9223372036854775808"),
            ("-9.007199254740993e15","-9007199254740993"),
            ("1e309","1"+String(repeating:"0",count:309)),
            ("100000000000000010e-1","10000000000000001"),
            ("0.000001e6","1"), ("-0e999","0")
        ]
        for (token,expected) in tokens {
            let input = template.replacingOccurrences(of:"\"eventSequence\":1",with:"\"eventSequence\":"+token)
            let decoded = try ContractCoding.canonicalDecode(AeostaraContract.AuditEvent.self,from:Data(input.utf8))
            XCTAssertEqual(decoded.eventSequence.decimalText,expected,token)
            XCTAssertEqual(try ContractCoding.canonicalDecode(AeostaraContract.AuditEvent.self,from:ContractCoding.canonicalEncode(decoded)),decoded,token)
        }
        for token in ["1.0000000000000001","0.99999999999999999","1.0000000000000001e0","1e-309"] {
            let input = template.replacingOccurrences(of:"\"eventSequence\":1",with:"\"eventSequence\":"+token)
            XCTAssertThrowsError(try ContractCoding.canonicalDecode(AeostaraContract.AuditEvent.self,from:Data(input.utf8)),token)
        }
        let fractionalBits = #"{"stateID":"fractional","coordinates":[1.0000000000000001,0,0,0,0,0,0,0,0],"sourceReference":"explicit-test","canonicalHash":"shape-only"}"#
        XCTAssertThrowsError(try ContractCoding.canonicalDecode(AeostaraContract.AshState.self,from:Data(fractionalBits.utf8)))
        let fractional = try CanonicalJSON.parse("1.0000000000000001")
        XCTAssertNotEqual(fractional,try CanonicalJSON.parse("1.0"))
        XCTAssertEqual(try CanonicalJSON.text(fractional),"1.0000000000000001")
        XCTAssertEqual(try CanonicalJSON.text(CanonicalJSON.parse("-0.0")),"-0.0")
        XCTAssertEqual(try CanonicalJSON.parse("-0.0"),try CanonicalJSON.parse("0.0"))
        XCTAssertEqual(try CanonicalJSON.parse(CanonicalJSON.encode(fractional)),fractional)
    }
    func testFreeJSONFieldsPreserveUnicodeIdentityAndRejectDuplicateAndUnknownMembers() throws {
        let source = try NativeAshBindingProvider.source(for:"ASH-STATE-STRUCTURE-001")
        let rule = try AeostaraContract.RuleReference(ruleID:"ASH-STATE-STRUCTURE-001",sourceReference:source,ruleFamily:"STATE")
        let evidence = try CanonicalJSON.parse(#"{"é":1,"e\u0301":2,"a.b":{},"":[],"present":null}"#)
        let envelope = try AeostaraContract.DiagnosticEnvelope(diagnosticID:"free-json",chainRootReference:"free-json",parentDiagnosticID:nil,diagnosticKind:.MAPPING,severity:.INFO,message:"Explicit codec test",ruleReferences:[rule],sourceReferences:[source],evidence:evidence)
        let decoded = try ContractCoding.canonicalDecode(AeostaraContract.DiagnosticEnvelope.self,from:ContractCoding.canonicalEncode(envelope))
        XCTAssertEqual(decoded.evidence.objectMembers?.count,5);XCTAssertEqual(decoded.evidence,evidence)
        if case .object(var fields) = envelope.jsonValue { fields.append(JSONMember("unknown",.bool(true)));XCTAssertThrowsError(try AeostaraContract.DiagnosticEnvelope(jsonValue:.object(fields))) }
        XCTAssertThrowsError(try ContractCoding.canonicalDecode(AeostaraContract.RuleReference.self,from:Data(#"{"ruleID":"a","ruleID":"b"}"#.utf8)))
    }
    func testPointerMutationRetainsEmptyContainersRootAndArrayOrder() throws {
        let document = try CanonicalJSON.parse(#"{"a.b":{"":[]},"items":[1,null,{}],"é":1,"e\u0301":2}"#)
        let withArray = try JSONPointer("/items/1").applying(.add,value:.bool(false),to:document)
        XCTAssertEqual(withArray.member("items")?.arrayValues,[.number(.integer("1")),.bool(false),.null,.object([])])
        let withEmpty = try JSONPointer("/a.b/").applying(.replace,value:.object([]),to:withArray)
        XCTAssertEqual(try JSONPointer("/a.b/").resolve(in:withEmpty),.object([]))
        XCTAssertEqual(try JSONPointer("").applying(.replace,value:.array([]),to:withEmpty),.array([]))
        XCTAssertThrowsError(try JSONPointer("/missing/child").applying(.add,value:.null,to:document))
        XCTAssertThrowsError(try JSONPointer("/items/01").applying(.remove,value:nil,to:document))
        XCTAssertThrowsError(try JSONPointer("/é").applying(.test,value:.number(.integer("2")),to:document))
        XCTAssertEqual(try JSONPointer("/e\u{301}").applying(.remove,value:nil,to:document).objectMembers?.count,3)
    }
